// The Webhook's JWT Auth checked this token against Landbright's JWKS: trust jwtPayload, not the body.
const e = $json.jwtPayload.event;
const d = e.data ?? {};
return { type: e.type, agent: d.agent, email: d.person?.email, name: d.person?.name, link: d.link, code: d.bindingMessage, scope: d.scope, expiresAt: d.expiresAt };

const r = $json;
const minutes = Math.max(1, Math.round((Date.parse(r.expiresAt) - Date.now()) / 60000));
const first = String(r.name ?? '').split(' ')[0] || 'there';
return {
  to: r.email,
  toName: r.name ?? r.email,
  subject: `${r.agent} asks to act for you`,
  text: [
    `Hi ${first},`,
    '',
    `${r.agent} asks Landbright for a token that says it acts for you.`,
    r.code ? `It shows the code ${r.code}: check it matches before you approve.` : '',
    '',
    `Approve or deny (you sign in to Landbright; the link works for ${minutes} min):`,
    r.link,
    '',
    'If you didn\'t start this, deny it.',
  ].filter((l, i, all) => l !== '' || all[i - 1] !== '').join('\n'),
};
